const out = [];
for (const r of [14,26,39,54,67,80,91,103,114,128]) {
  const c = wb.getRange('B'+r);
  const raw = c.getValues()[0][0];
  const before = c.getStyle().getNumberFormat?.();
  const m = /^[A-Z]{2,3} ?(\d+)$/.exec(raw);
  if (!m) { out.push(`B${r} NO MATCH ${JSON.stringify(raw)}`); continue; }
  c.setValue(Number(m[1]));
  out.push(`B${r} ${JSON.stringify(raw)} fmt=${before} -> ${JSON.stringify(c.getValues()[0][0])} text=${c.getCell?.().getText?.()}`);
}
log(out.join('\n'));
wb.getRange('B14:B137').getCounts()

